<?php
require_once '../includes/auth.php'; require_role('admin'); require_once '../config/db.php'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??'');$date=$_POST['date']??'';$desc=trim($_POST['description']??'');if($title&&$date&&$desc){$stmt=$conn->prepare("INSERT INTO tbl_events(title,date,description,created_by) VALUES(?,?,?,?)");$stmt->bind_param("ssss",$title,$date,$desc,$_SESSION['username']);$stmt->execute();$msg='Event added.';}}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$stmt=$conn->prepare("DELETE FROM tbl_events WHERE id=?");$stmt->bind_param("i",$id);$stmt->execute();header('Location: events.php');exit;}
$events=$conn->query("SELECT * FROM tbl_events ORDER BY date ASC");$page_title='Academic Calendar';require '../includes/header.php'; ?><div class="row g-4"><div class="col-lg-4"><div class="panel"><h5>Add Event</h5><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><form method="POST"><input class="form-control mb-2" name="title" placeholder="Event title" required><input class="form-control mb-2" type="date" name="date" required><textarea class="form-control mb-2" name="description" rows="4" placeholder="Description" required></textarea><button class="btn btn-primary w-100">Add Event</button></form></div></div><div class="col-lg-8"><div class="panel"><h5>Events</h5><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Date</th><th>Title</th><th>Created By</th><th></th></tr></thead><tbody><?php while($ev=$events->fetch_assoc()):?><tr><td><?php echo e($ev['date']);?></td><td><?php echo e($ev['title']);?></td><td><?php echo e($ev['created_by']);?></td><td><a class="btn btn-sm btn-outline-danger" href="?delete=<?php echo $ev['id'];?>" data-confirm="Delete this event?">Delete</a></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php require '../includes/footer.php'; ?>
